l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'dojib higomoka') query
  WHERE workspace_id = ANY (ARRAY['83befea0-9bb7-8749-19f4-1b0c2033e699'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '6e1d417e-829d-27d4-fa00-9409beeda39a'::uuid
       OR '6e1d417e-829d-27d4-fa00-9409beeda39a'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

