l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula kaliqupa') query
  WHERE workspace_id = ANY (ARRAY['d62db9be-a9ed-8d72-9c6b-b2ac259abad8'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '2826ad62-29f8-c4a4-2645-86f83e3c3aa0'::uuid
       OR '2826ad62-29f8-c4a4-2645-86f83e3c3aa0'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

