  FROM ai_chunks, websearch_to_tsquery('simple', 'panikug wajoqo vogula') query
  WHERE workspace_id = ANY (ARRAY['9773fc35-d3e1-a3b9-6d88-bbfaae3b6c2a'::uuid,'672451b7-bfca-5f53-82c8-f5f0a9bd4ef8'::uuid]) AND (
