l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'cutic jofados') query
  WHERE workspace_id = ANY (ARRAY['fbb742d9-bd39-ad72-c315-c88f964bd6ad'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '69a6573d-1d9d-ed66-e8a3-8fd3ee041c6f'::uuid
       OR '69a6573d-1d9d-ed66-e8a3-8fd3ee041c6f'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

