l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula noterepu paki') query
  WHERE workspace_id = ANY (ARRAY['9f7f5d98-4cea-2346-8dc1-80d8a4a98b58'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '3af1b721-be16-afe8-7118-8e6bcc394ff5'::uuid
       OR '3af1b721-be16-afe8-7118-8e6bcc394ff5'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

