  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula pero kekokida') query
  WHERE workspace_id = ANY (ARRAY['c2e7af5f-6e50-5671-af79-5de6e6000a01'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
