l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'wukub kobak') query
  WHERE workspace_id = ANY (ARRAY['274c52d3-5057-3684-425b-2046ac24f696'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '6055143c-354c-438f-6448-cb616c64d0d0'::uuid
       OR '6055143c-354c-438f-6448-cb616c64d0d0'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

