l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'kakawem vofu') query
  WHERE workspace_id = ANY (ARRAY['c435303a-1a82-a1ce-54e5-abc64db6534a'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '515a2ea8-320d-7d93-d063-1bcd4ee82ef4'::uuid
       OR '515a2ea8-320d-7d93-d063-1bcd4ee82ef4'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

