l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'qolufike jecu') query
  WHERE workspace_id = ANY (ARRAY['6c12d050-3c3c-10cd-553f-f8e17e6ab50b'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '96bd4d26-97bd-53a2-3a27-a356fc80ea6b'::uuid
       OR '96bd4d26-97bd-53a2-3a27-a356fc80ea6b'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

