l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'manec wopale deloza') query
  WHERE workspace_id = ANY (ARRAY['662754a7-d8f8-1085-0a97-1f99ec5b6470'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '18319492-4ad3-192e-e28a-ec9a770db291'::uuid
       OR '18319492-4ad3-192e-e28a-ec9a770db291'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

