l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'pivot jacow cabikiw') query
  WHERE workspace_id = ANY (ARRAY['db456c4f-078b-b650-b39a-c8d57f1586fd'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '4e30cf3c-138a-9c5a-5790-fa65c6a10d17'::uuid
       OR '4e30cf3c-138a-9c5a-5790-fa65c6a10d17'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

