  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula jofados') query
  WHERE workspace_id = ANY (ARRAY['a77aaffa-044f-e029-c4a8-fb411dc05a63'::uuid,'e72c9607-d777-d2e9-09ed-644168a39c90'::uuid]) AND (
