  FROM ai_chunks, websearch_to_tsquery('simple', 'kejozone relida zezo') query
  WHERE workspace_id = ANY (ARRAY['f9c03c80-cafd-a3da-1f00-0ffaee68c91e'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'bb35d59b-e3e1-1e32-7e70-cb0814db7178'::uuid
