  FROM ai_chunks, websearch_to_tsquery('simple', 'lepilaqa cinapaf') query
  WHERE workspace_id = ANY (ARRAY['9b4b1b16-b6a2-6725-fb15-27bb9a0c4745'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'a3194124-3a87-1c9e-dc49-2d58a56e8c80'::uuid
