l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'lafeqo kaqetum ciceda') query
  WHERE workspace_id = ANY (ARRAY['4b5d1d21-1c98-d692-4605-51948ab5773e'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'a0c0cab8-d988-e4a7-9d10-15ef5a7c887c'::uuid
       OR 'a0c0cab8-d988-e4a7-9d10-15ef5a7c887c'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

