  WHERE workspace_id = ANY (ARRAY['6c87635b-3220-d1ce-57fb-cafbb10be749'::uuid,'8c918e45-acb6-194b-cf3c-1f0d990029e1'::uuid,'1ac8b8ad-725f-e26b-dda1-6749d1e1475c'::uuid]) AND (
