  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula hewu dupokod') query
  WHERE workspace_id = ANY (ARRAY['6970910d-8be3-88c0-9ec5-5eb759b6c9ca'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '42eb9701-c8ce-d285-cf8a-ef4b885f625c'::uuid
