  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula puho') query
  WHERE workspace_id = ANY (ARRAY['a5a2fa26-bbe6-b447-3b77-bfc4c8c2263e'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '3f5fdf3b-234b-9d08-85ec-6f7e67708026'::uuid
