  FROM ai_chunks, websearch_to_tsquery('simple', 'viqow vogula') query
  WHERE workspace_id = ANY (ARRAY['7597e0ad-4151-936b-fd0a-6a4cf90c3dcd'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '40c0a4f9-b743-407f-0134-b29781e97e96'::uuid
       OR '40c0a4f9-b743-407f-0134-b29781e97e96'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

