  FROM ai_chunks, websearch_to_tsquery('simple', 'wuze zejaz bicifu') query
  WHERE workspace_id = ANY (ARRAY['4e6e2403-8585-761d-3cd2-a808be71d8df'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'fe052aec-ae25-1c6a-a0ba-da0e26afe8b2'::uuid
