l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula wezi') query
  WHERE workspace_id = ANY (ARRAY['9763e5bb-4c5c-a995-a240-41024f3c0932'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '5d3fa88a-c6e9-0e0a-dc6b-9c507c06c06c'::uuid
       OR '5d3fa88a-c6e9-0e0a-dc6b-9c507c06c06c'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

