l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula metil') query
  WHERE workspace_id = ANY (ARRAY['7bc91229-dc77-912c-9e9a-655370285533'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'a801c167-d609-3d06-ad6c-1e81f5e946c7'::uuid
       OR 'a801c167-d609-3d06-ad6c-1e81f5e946c7'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

