l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'dazona vofu') query
  WHERE workspace_id = ANY (ARRAY['834bcade-7364-9532-a36c-fdf29935ff59'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '3c664295-d8cb-9288-5225-af5cd7b2a7b6'::uuid
       OR '3c664295-d8cb-9288-5225-af5cd7b2a7b6'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

