l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'pero vogula') query
  WHERE workspace_id = ANY (ARRAY['54dc3ae9-e3be-ad98-b963-37f2f7243997'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '87f8b997-657f-6636-78f2-8968cde924de'::uuid
       OR '87f8b997-657f-6636-78f2-8968cde924de'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

