  FROM ai_chunks, websearch_to_tsquery('simple', 'pugaje qokoka bowoduw') query
  WHERE workspace_id = ANY (ARRAY['10c51c13-9e96-ba2a-d9e2-a4bfcb17d0e8'::uuid]) AND (
       visibility = 'shared'
