l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'dupokod qavegaf') query
  WHERE workspace_id = ANY (ARRAY['dad97666-1fcd-1b79-050b-5e4c801da60e'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'c728b312-d53d-bb81-98a5-6634b014c536'::uuid
       OR 'c728b312-d53d-bb81-98a5-6634b014c536'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

