  FROM ai_chunks, websearch_to_tsquery('simple', 'bucop jofados') query
  WHERE workspace_id = ANY (ARRAY['df47b2e2-618f-efcc-1bee-1b60d173e246'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '5f598439-3d19-69e0-90f1-97d4b2ee18d5'::uuid
