  FROM ai_chunks, websearch_to_tsquery('simple', 'jacow pobabiq kobak') query
  WHERE workspace_id = ANY (ARRAY['22a473c4-1e18-dff2-7699-fc7860f30800'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
