l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'jofados muwu') query
  WHERE workspace_id = ANY (ARRAY['4a3c5757-96cc-ef73-27fb-f5d2c3450b88'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '9db7f2bb-5772-a3b4-d5cb-57bd1e4da773'::uuid
       OR '9db7f2bb-5772-a3b4-d5cb-57bd1e4da773'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

