  FROM ai_chunks, websearch_to_tsquery('simple', 'pero dunazofu') query
  WHERE workspace_id = ANY (ARRAY['4019fefd-f4df-d3a6-6e7b-2a4f3a91a421'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '28c55fb8-474c-5af1-7232-b74250aab706'::uuid
