  FROM ai_chunks, websearch_to_tsquery('simple', 'kubunere kimefeze') query
  WHERE workspace_id = ANY (ARRAY['48b92308-1b79-6249-b5d3-bd8aae23156d'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '9e872e62-e664-7be7-634b-3af642c73bcf'::uuid
       OR '9e872e62-e664-7be7-634b-3af642c73bcf'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

