  FROM ai_chunks, websearch_to_tsquery('simple', 'kuca zezo kupicin') query
  WHERE workspace_id = ANY (ARRAY['4ac5d606-13d7-55d7-865c-edc8879d6bd8'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
