  FROM ai_chunks, websearch_to_tsquery('simple', 'bulacubu kubunere zurefo') query
  WHERE workspace_id = ANY (ARRAY['1960cd8e-8847-ccf4-fc40-942016f8a3d9'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '80f21480-39d8-5524-64df-70df06e67b17'::uuid
       OR '80f21480-39d8-5524-64df-70df06e67b17'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
