l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'relida jofados pero') query
  WHERE workspace_id = ANY (ARRAY['014a7ff0-73c0-bf0c-48ab-b98e32d6fb03'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'f30fbf86-dfd6-ca75-1aef-fe0c104b2452'::uuid
