  FROM ai_chunks, websearch_to_tsquery('simple', 'lepilaqa kubunere') query
  WHERE workspace_id = ANY (ARRAY['a1a38181-6428-8967-b753-4a5815bfb70a'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '2264567d-9d65-844d-5627-58d33d7cc9bd'::uuid
