l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'juhin zufaqimo') query
  WHERE workspace_id = ANY (ARRAY['7f9e75f1-a2b7-b54c-b1f9-dba4add4dc87'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '8051dd87-17ed-d1cf-5314-1390bc257bcb'::uuid
       OR '8051dd87-17ed-d1cf-5314-1390bc257bcb'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

