  FROM ai_chunks, websearch_to_tsquery('simple', 'ruzen relida rulav') query
  WHERE workspace_id = ANY (ARRAY['8411aa70-e689-31b2-85c1-e7512345df1c'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'd88e2158-6dcf-8046-1cc7-c2d458de6ab6'::uuid
       OR 'd88e2158-6dcf-8046-1cc7-c2d458de6ab6'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

