l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'newuhaf vogula befubeq') query
  WHERE workspace_id = ANY (ARRAY['8ee37ac8-89ea-d802-0e16-73cbf6eb9318'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '30e3a5f8-52b2-4342-096b-21678974518d'::uuid
       OR '30e3a5f8-52b2-4342-096b-21678974518d'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

