l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula jezev') query
  WHERE workspace_id = ANY (ARRAY['73a829ec-24de-31ef-b26d-24f3537df98f'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '88a66eb6-874e-4e81-0361-f15fe12dfd78'::uuid
       OR '88a66eb6-874e-4e81-0361-f15fe12dfd78'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

