l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula locu') query
  WHERE workspace_id = ANY (ARRAY['a33a9e18-5a62-7347-0e6a-7e84c935e0ee'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '504da222-e71e-4d8c-d663-eaa7a0c8d2cb'::uuid
       OR '504da222-e71e-4d8c-d663-eaa7a0c8d2cb'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

