  FROM ai_chunks, websearch_to_tsquery('simple', 'dejeh tujo') query
  WHERE workspace_id = ANY (ARRAY['8f7fe4e9-431f-b969-47b0-3c5490994ec4'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'f3b812b8-e449-eae8-2386-2ab80ed1c70f'::uuid
