  FROM ai_chunks, websearch_to_tsquery('simple', 'pugaje fimodi') query
  WHERE workspace_id = ANY (ARRAY['20b8e5e7-2b0a-a214-c9d6-7dffc1a4397d'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
