l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'dupokod kubunere') query
  WHERE workspace_id = ANY (ARRAY['e902f8b5-907c-25d1-756a-57d062e941a8'::uuid,'0d702a5f-a07f-a663-ddda-a8f40705ec55'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '4d2d1761-a9d7-34db-c8d2-167a1365d2e5'::uuid
       OR '4d2d1761-a9d7-34db-c8d2-167a1365d2e5'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

