l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'doloziw lovet') query
  WHERE workspace_id = ANY (ARRAY['c6fcc598-3646-1d5a-b2f7-35f9992b4ade'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '11e941c7-3288-cff3-6698-dd6470c69e31'::uuid
       OR '11e941c7-3288-cff3-6698-dd6470c69e31'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

