l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'mileru todas') query
  WHERE workspace_id = ANY (ARRAY['e2e3f066-73b0-10b0-0048-c5732d4393be'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'ba2654ed-1a1f-eae3-9f14-e324a7328b81'::uuid
       OR 'ba2654ed-1a1f-eae3-9f14-e324a7328b81'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

