l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'wifot jofados') query
  WHERE workspace_id = ANY (ARRAY['25c2a211-875b-914f-c985-70a967667dcc'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'e2fe11f3-b798-c87d-2a1c-39d8ec244662'::uuid
       OR 'e2fe11f3-b798-c87d-2a1c-39d8ec244662'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

