  FROM ai_chunks, websearch_to_tsquery('simple', 'kohediji vogula') query
  WHERE workspace_id = ANY (ARRAY['41c098dd-15cb-697c-9985-957fcd9ff7cd'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'b3c2debe-d017-266b-c202-986457f9842c'::uuid
