  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula zurefo jofados') query
  WHERE workspace_id = ANY (ARRAY['8fe2ce13-310d-8530-e996-2a7e776184a1'::uuid,'c63e6991-a789-0972-5117-548b149ce58c'::uuid]) AND (
