l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'ralizog tokepub wago') query
  WHERE workspace_id = ANY (ARRAY['f1039a06-9467-897e-998b-5614f1ff2b41'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '0563a76d-c011-e045-a7a5-b8c5b2b62673'::uuid
       OR '0563a76d-c011-e045-a7a5-b8c5b2b62673'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

