  FROM ai_chunks, websearch_to_tsquery('simple', 'kupicin vogula') query
  WHERE workspace_id = ANY (ARRAY['7b3efbcf-b231-dcfa-0dd6-d46121bc1b88'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'b48ad954-cbef-3b5f-1d76-43bcd516ce44'::uuid
