  FROM ai_chunks, websearch_to_tsquery('simple', 'kobak qavegaf') query
  WHERE workspace_id = ANY (ARRAY['05cbb654-dd15-3a58-1c1d-7e2b39715edb'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'b0019557-f98f-6025-e65f-a5037981831e'::uuid
       OR 'b0019557-f98f-6025-e65f-a5037981831e'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

