l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'jofados dupokod') query
  WHERE workspace_id = ANY (ARRAY['6b61c5c6-9a04-efe2-60ff-a51315e532c3'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '82f94ed4-bb07-aaf9-0062-04b8e7a93cdd'::uuid
       OR '82f94ed4-bb07-aaf9-0062-04b8e7a93cdd'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

