  FROM ai_chunks, websearch_to_tsquery('simple', 'jofados sida') query
  WHERE workspace_id = ANY (ARRAY['40a13dab-812f-7d9f-9f71-5a7b36378862'::uuid,'1e58acbf-9f97-8c6d-105a-b2200378e67e'::uuid]) AND (
