  FROM ai_chunks, websearch_to_tsquery('simple', 'kekokida vifivofo') query
  WHERE workspace_id = ANY (ARRAY['41b6c579-67bd-23b7-d1e0-b7402c7de53a'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '7f95d221-3207-f1de-5a36-09d1dd58b4d5'::uuid
