  FROM ai_chunks, websearch_to_tsquery('simple', 'civukoju vogula vofu') query
  WHERE workspace_id = ANY (ARRAY['e5d08587-7e58-a971-02c8-73cf72723e77'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '5b73c90e-df86-1a38-6a68-51c51737717e'::uuid
       OR '5b73c90e-df86-1a38-6a68-51c51737717e'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

