l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'wofim hazi') query
  WHERE workspace_id = ANY (ARRAY['a5b5c73b-87e4-5371-b60a-c9fdc12b7346'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'ace4445c-d24f-0034-87ea-2f6a9089abbd'::uuid
       OR 'ace4445c-d24f-0034-87ea-2f6a9089abbd'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

