  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula wagusuco bikoh') query
  WHERE workspace_id = ANY (ARRAY['449604cf-84a4-5bc8-7fc7-e07903dcecb1'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
