l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'romafu vogula') query
  WHERE workspace_id = ANY (ARRAY['5505190f-2c7d-8f5d-cdb9-b39ca589dad0'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'd7f7c131-9aab-208d-52d9-bbf3bb4f88b2'::uuid
       OR 'd7f7c131-9aab-208d-52d9-bbf3bb4f88b2'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

