l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'ralizog nisudek') query
  WHERE workspace_id = ANY (ARRAY['fbefb164-ecf3-aaa3-f5a9-9c730a4807d2'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'cbaf0fa4-8c26-6176-310e-4c3f36257cb7'::uuid
       OR 'cbaf0fa4-8c26-6176-310e-4c3f36257cb7'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

