l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'rulav mukuvaso') query
  WHERE workspace_id = ANY (ARRAY['d780de14-7280-11d8-9765-bd1d95d0ed1f'::uuid,'4864adc6-4b17-f61f-828f-c8d590411db8'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '2b288444-9eb4-4d36-60e3-af2d39e9514f'::uuid
       OR '2b288444-9eb4-4d36-60e3-af2d39e9514f'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

