l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'mewozufu huzora') query
  WHERE workspace_id = ANY (ARRAY['c51e02e2-7d91-de75-ec4e-4d7b06ae4748'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '9d29308e-51df-c891-e79e-372ed3624ca9'::uuid
       OR '9d29308e-51df-c891-e79e-372ed3624ca9'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

