l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'pero dofoqed') query
  WHERE workspace_id = ANY (ARRAY['4ead29a7-ad5f-3056-a266-7184a0bec483'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'b7e9b475-0097-a1a4-0c8e-5ff7fe21b237'::uuid
       OR 'b7e9b475-0097-a1a4-0c8e-5ff7fe21b237'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

