l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'gabu qubejevi') query
  WHERE workspace_id = ANY (ARRAY['88bb7f42-8db8-f23b-4c3a-392583022645'::uuid,'9672da6b-f556-698d-f48d-24ef4cbd96d7'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'd6fd8cbb-2e01-0fcc-baf7-711b42b752ef'::uuid
       OR 'd6fd8cbb-2e01-0fcc-baf7-711b42b752ef'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

