  FROM ai_chunks, websearch_to_tsquery('simple', 'jecu vezi hequder') query
  WHERE workspace_id = ANY (ARRAY['93fc316e-c3be-77ce-7f7e-1dfd8de25eff'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'ba918d1b-a353-6037-ef21-c0814f660ddc'::uuid
       OR 'ba918d1b-a353-6037-ef21-c0814f660ddc'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

