  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula gorelevu') query
  WHERE workspace_id = ANY (ARRAY['332ebd82-6933-dd85-d169-9dd18989fc5e'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '2dc6b436-d658-9cc6-3f8c-f3b14e1cf02e'::uuid
