l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'kubunere coki') query
  WHERE workspace_id = ANY (ARRAY['8e081b89-1dad-4851-e109-1b7f7fc789eb'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'ef1f5dd4-1047-d892-5a02-c7e5c9c1b419'::uuid
       OR 'ef1f5dd4-1047-d892-5a02-c7e5c9c1b419'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

