l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'relida rosejil') query
  WHERE workspace_id = ANY (ARRAY['700359f3-45f8-6dbc-909b-45b4e693016f'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'be448629-0140-3370-204d-d6c98cea3d0d'::uuid
