l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vofu vogula bokev') query
  WHERE workspace_id = ANY (ARRAY['234de095-6b40-0433-f500-f411516556fa'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '5a525090-e38c-0543-9f80-7012b450f959'::uuid
