  FROM ai_chunks, websearch_to_tsquery('simple', 'gopawu nuqemo kekokida') query
  WHERE workspace_id = ANY (ARRAY['9a58560c-31a6-1081-091e-52b1d1cce45f'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'd4883760-0c00-a931-e1cf-c659de191dd3'::uuid
       OR 'd4883760-0c00-a931-e1cf-c659de191dd3'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
