  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula wufuzo') query
  WHERE workspace_id = ANY (ARRAY['ebce41a8-ecbf-1073-846b-ea76ec8a7b12'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'ab08d0b1-1920-d99e-8abc-061fa7a0309e'::uuid
       OR 'ab08d0b1-1920-d99e-8abc-061fa7a0309e'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

