  FROM ai_chunks, websearch_to_tsquery('simple', 'jecu putaqit fala') query
  WHERE workspace_id = ANY (ARRAY['f7981971-6bdc-b706-2c6c-0e997f9fb1c3'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'c7836c6d-8d23-2909-b679-c7e1db36fd5e'::uuid
