  FROM ai_chunks, websearch_to_tsquery('simple', 'pero jugikul') query
  WHERE workspace_id = ANY (ARRAY['91902914-157a-ccdc-c833-35fd0dd7661a'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '3f502eb7-0aeb-5532-6a38-2fb3ed23b97b'::uuid
