  FROM ai_chunks, websearch_to_tsquery('simple', 'nudepig qiliqov') query
  WHERE workspace_id = ANY (ARRAY['1a478e27-9b12-99dd-22c4-98298beb0cec'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'b19ff1d9-34a5-74ec-9846-d67977a05e9d'::uuid
       OR 'b19ff1d9-34a5-74ec-9846-d67977a05e9d'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

