l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'jasu vogula coki') query
  WHERE workspace_id = ANY (ARRAY['72093187-f69b-dea8-a1ac-33bccb3aa170'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'bc38baef-44bc-cc88-6099-1dfbe0f21248'::uuid
       OR 'bc38baef-44bc-cc88-6099-1dfbe0f21248'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

