l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'tokepub jofados palew') query
  WHERE workspace_id = ANY (ARRAY['d521df2a-3e87-6cfd-f6c4-b2320e67a318'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '5c9c6783-4d41-04a7-335f-eccabad253ae'::uuid
       OR '5c9c6783-4d41-04a7-335f-eccabad253ae'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

