l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'romafu tutelo') query
  WHERE workspace_id = ANY (ARRAY['860602f7-de40-0c07-ba57-4ccd00f4c990'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '4333af8d-fbdd-5f7d-6062-4e202c14ab7e'::uuid
       OR '4333af8d-fbdd-5f7d-6062-4e202c14ab7e'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

