  FROM ai_chunks, websearch_to_tsquery('simple', 'gigow vogula') query
  WHERE workspace_id = ANY (ARRAY['3452b1de-0443-6cea-5d9e-c447c7c9f19c'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'c2354cd0-c03b-0eeb-d1dd-02615540ba2e'::uuid
