  FROM ai_chunks, websearch_to_tsquery('simple', 'kobak vogula korojiw') query
  WHERE workspace_id = ANY (ARRAY['276274a4-e6ac-acde-d647-18d0129a2b99'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '97d52f16-f953-ae25-6060-31596f848a08'::uuid
       OR '97d52f16-f953-ae25-6060-31596f848a08'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

