l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'tuneso wajoqo') query
  WHERE workspace_id = ANY (ARRAY['34d943be-10e0-a8f6-89c0-5458c9622958'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '574622c7-4f21-0daa-5606-c70a60f5e190'::uuid
       OR '574622c7-4f21-0daa-5606-c70a60f5e190'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

