l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'sarone hihubad') query
  WHERE workspace_id = ANY (ARRAY['042fe782-3747-ad9c-48bd-33d72bfbcc43'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '31348ab0-66af-f583-50d4-ba6f638f33f8'::uuid
       OR '31348ab0-66af-f583-50d4-ba6f638f33f8'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

