  FROM ai_chunks, websearch_to_tsquery('simple', 'wufuzo lepilaqa') query
  WHERE workspace_id = ANY (ARRAY['2c022a96-a2cf-2232-5229-d24f6173dac4'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '9564da1c-b3bc-04ea-c2de-aeeb264f312d'::uuid
