  FROM ai_chunks, websearch_to_tsquery('simple', 'sazo vogula') query
  WHERE workspace_id = ANY (ARRAY['de12b35c-24b7-b3d2-601b-0f1784a56532'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'c65ee847-48a8-96b0-5bcf-d336420a5d92'::uuid
