  FROM ai_chunks, websearch_to_tsquery('simple', 'romafu kubunere') query
  WHERE workspace_id = ANY (ARRAY['08ca1b10-1846-4809-52af-0bdac1579416'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '7c5326f1-db2e-b98c-5ca8-0768b7d60610'::uuid
       OR '7c5326f1-db2e-b98c-5ca8-0768b7d60610'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

