l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'pero gabokel') query
  WHERE workspace_id = ANY (ARRAY['56c64eb0-49ab-344d-2e70-b057725b37b6'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '63882226-5524-dbfd-92e7-2450b497f478'::uuid
       OR '63882226-5524-dbfd-92e7-2450b497f478'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

