l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula zezo') query
  WHERE workspace_id = ANY (ARRAY['4bee0c75-35ad-5c13-5c95-440144a23235'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '3ddd9dcb-c819-e97c-725b-41f8c1b47295'::uuid
       OR '3ddd9dcb-c819-e97c-725b-41f8c1b47295'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

