l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'siki tukuse') query
  WHERE workspace_id = ANY (ARRAY['1bfe717a-aced-c8ef-6f6b-7240c16a5bad'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '6b898b0d-487a-cbb9-06fa-10ac231479f6'::uuid
       OR '6b898b0d-487a-cbb9-06fa-10ac231479f6'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

