l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula kubunere') query
  WHERE workspace_id = ANY (ARRAY['952ae830-9696-9044-593f-d5cff186ed0c'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'f8621f90-e8ad-f9a0-55c8-9e864e2cb61c'::uuid
       OR 'f8621f90-e8ad-f9a0-55c8-9e864e2cb61c'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

