l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'pero sivopiba') query
  WHERE workspace_id = ANY (ARRAY['e0b65d88-3d2f-50c7-3ac0-1b6aef22072b'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '4d5e366c-b3bd-0d76-570b-7500b9f5bead'::uuid
       OR '4d5e366c-b3bd-0d76-570b-7500b9f5bead'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

