l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'juso cidavej') query
  WHERE workspace_id = ANY (ARRAY['f0748425-3a49-209c-b438-9438c3e2a9eb'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'b9f7685d-a5f5-9b08-e797-a2fc8b6551aa'::uuid
       OR 'b9f7685d-a5f5-9b08-e797-a2fc8b6551aa'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

