  FROM ai_chunks, websearch_to_tsquery('simple', 'tovevo mahofetu vogula') query
  WHERE workspace_id = ANY (ARRAY['a89913f9-bce9-e901-9229-c131d0401e0c'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'dc0af247-60a1-a918-923c-ae492f81f1d7'::uuid
