  FROM ai_chunks, websearch_to_tsquery('simple', 'pihonuni bajo vuvekosa') query
  WHERE workspace_id = ANY (ARRAY['89d44f88-3cf4-f704-f345-17f43b8a9f90'::uuid]) AND (
