  FROM ai_chunks, websearch_to_tsquery('simple', 'nepato rosejil') query
  WHERE workspace_id = ANY (ARRAY['12768399-caa9-2564-317a-6b682c5bc116'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
