  FROM ai_chunks, websearch_to_tsquery('simple', 'vudi vogula') query
  WHERE workspace_id = ANY (ARRAY['411d6ec4-4e71-dd09-a2d6-61b648b63cc6'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '69a4bf96-4e42-b290-cee5-dfa9ad484d52'::uuid
       OR '69a4bf96-4e42-b290-cee5-dfa9ad484d52'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

