l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vofu sota qemet') query
  WHERE workspace_id = ANY (ARRAY['5a953567-0764-6cf0-64bf-d6fb630953fa'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '7353d765-e313-1c0f-89a6-34392d99e4e3'::uuid
       OR '7353d765-e313-1c0f-89a6-34392d99e4e3'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

