l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'kikifobo pedi kubunere') query
  WHERE workspace_id = ANY (ARRAY['e64da965-0b29-20c8-e711-50ee7efe53df'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '89cf33e2-d9d8-6900-3f55-0b0ea3ef3b62'::uuid
