l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'suta pero') query
  WHERE workspace_id = ANY (ARRAY['eed7e839-0e42-9459-f5c1-c29e0ed133fb'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '6447f9b9-099b-84eb-0955-4cc82b344236'::uuid
       OR '6447f9b9-099b-84eb-0955-4cc82b344236'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

