  FROM ai_chunks, websearch_to_tsquery('simple', 'kubunere johalus cife') query
  WHERE workspace_id = ANY (ARRAY['1b3f9115-d338-4b18-7c03-53cbe6215eaa'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
