l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'pero semi') query
  WHERE workspace_id = ANY (ARRAY['532c4d1c-2edc-ef14-939b-5113b1bbe919'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '30fb0add-b112-6c2b-4e36-558b3afd25bc'::uuid
       OR '30fb0add-b112-6c2b-4e36-558b3afd25bc'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

