l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'sakum kubunere') query
  WHERE workspace_id = ANY (ARRAY['eb092c71-7cc8-1c2e-4486-653d5572ac26'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'a1999fab-a96f-cedb-356d-c37c6e3a5fde'::uuid
       OR 'a1999fab-a96f-cedb-356d-c37c6e3a5fde'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

