  FROM ai_chunks, websearch_to_tsquery('simple', 'rosejil tuco') query
  WHERE workspace_id = ANY (ARRAY['89c104d4-400d-6794-d31a-4b2e025d9f3f'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'aa6958c5-a768-7a76-2d75-b9257b8b064f'::uuid
