l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'kilejog kobak zakama') query
  WHERE workspace_id = ANY (ARRAY['62a5618b-ea14-7428-9ccd-d4dd766fe559'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'daf34810-7aa1-1aaf-1f3d-2120c99567ad'::uuid
       OR 'daf34810-7aa1-1aaf-1f3d-2120c99567ad'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

