l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'ciceda vogula') query
  WHERE workspace_id = ANY (ARRAY['21a9ae09-8aaa-0d62-841c-912cb3f71c46'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'ba000e04-58cd-b67d-ea67-4e03f6ea5a30'::uuid
       OR 'ba000e04-58cd-b67d-ea67-4e03f6ea5a30'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

