l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'wizo dule') query
  WHERE workspace_id = ANY (ARRAY['3d0d922f-7893-6c3b-c288-82195933910a'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'eb22f47b-6b5a-4fa7-af9f-bce23f113f88'::uuid
       OR 'eb22f47b-6b5a-4fa7-af9f-bce23f113f88'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

