  FROM ai_chunks, websearch_to_tsquery('simple', 'dutubil zezo') query
  WHERE workspace_id = ANY (ARRAY['0a80b7f9-46cd-798e-0e7b-8751c23a839c'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '0227d459-cc1c-9fef-66bb-484916615f58'::uuid
       OR '0227d459-cc1c-9fef-66bb-484916615f58'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

