  FROM ai_chunks, websearch_to_tsquery('simple', 'relida kekokida kobak') query
  WHERE workspace_id = ANY (ARRAY['a89e88c7-54e6-c5c5-a618-15ba983d94b5'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '5132ad0d-9bd9-12d9-1629-83af69ab4f53'::uuid
