  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula cedem jofados') query
  WHERE workspace_id = ANY (ARRAY['63a5a593-2667-d62e-2746-a988f6e5ab11'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'cc293720-b2b4-7f25-9dfc-50e54d35fdaf'::uuid
