  FROM ai_chunks, websearch_to_tsquery('simple', 'pero sibafek') query
  WHERE workspace_id = ANY (ARRAY['8d13709f-4e7c-ccf0-87e7-733030cdcd24'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '713f3849-f9d8-4965-e110-2ab91dfe49c7'::uuid
       OR '713f3849-f9d8-4965-e110-2ab91dfe49c7'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

