l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula kevid') query
  WHERE workspace_id = ANY (ARRAY['b1032a87-fc71-4fbc-3880-4f55adedb900'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'a5c5159a-aed3-a9d7-76e0-70a3769ba4c2'::uuid
       OR 'a5c5159a-aed3-a9d7-76e0-70a3769ba4c2'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

