l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula romafu') query
  WHERE workspace_id = ANY (ARRAY['505d53ed-b805-1283-1879-1c373e4da184'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = '2301ff9e-693a-8c13-001d-6fb52c878dfa'::uuid
       OR '2301ff9e-693a-8c13-001d-6fb52c878dfa'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

