  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula laqokoko wopale') query
  WHERE workspace_id = ANY (ARRAY['dff553db-b2e9-37f3-5341-e43480d69289'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'b21b3fc3-4bf5-da35-1f43-3099dd933b8a'::uuid
       OR 'b21b3fc3-4bf5-da35-1f43-3099dd933b8a'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

