  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula dupokod kaqam') query
  WHERE workspace_id = ANY (ARRAY['156b1fd0-1a09-ad59-c51b-31fa3e48699b'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'd15f3354-a51c-23df-dfb9-9265b83fc1de'::uuid
       OR 'd15f3354-a51c-23df-dfb9-9265b83fc1de'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;

