l AS (
  SELECT id, row_number() OVER (ORDER BY ts_rank_cd(tsv, query) DESC) AS r
  FROM ai_chunks, websearch_to_tsquery('simple', 'vogula kevid racob') query
  WHERE workspace_id = ANY (ARRAY['bc4ad00e-e1bc-2be2-40d3-be13d7c9d134'::uuid]) AND (
       visibility = 'shared'
       OR visibility = 'public'
       OR owner_id = 'ba7fbb2b-68f9-b0fe-06b9-7a89a6d45c0e'::uuid
       OR 'ba7fbb2b-68f9-b0fe-06b9-7a89a6d45c0e'::uuid = ANY (collaborator_ids)
     ) AND tsv @@ query
  ORDER BY ts_rank_cd(tsv, query) DESC LIMIT 50
)
SELECT id, sum(1.0 / (60 + r)) AS score
FROM (SELECT * FROM v UNION ALL SELECT * FROM l) u
GROUP BY id ORDER BY score DESC LIMIT 20;
